      "parameters": {
        "jsCode": "// Cleans what comes from the form and decides if it's usable.\n// The Webhook node puts the request body into .body\nconst c = $input.first().json.body || $input.first().json;\n\n// Trims extra whitespace and keeps text manageable\nconst t = (v) => String(v == null ? '' : v).trim().replace(/\\s+/g, ' ');\nconst errores = [];\n\nconst nombre   = t(c.nombre);\nconst email    = t(c.email).toLowerCase();\nconst mensaje  = t(c.mensaje);\nconst empresa  = t(c.empresa);\nconst telefono = t(c.telefono).replace(/[^0-9+]/g, '');\n\nif (nombre.length < 2)     errores.push('nombre');\nif (mensaje.length < 10)   errores.push('mensaje_corto');\nif (mensaje.length > 2000) errores.push('mensaje_largo');\n\n// A real email: something, at, something, dot, two letters minimum\nif (!/^[^\\s@]+@[^\\s@]+\\.[a-z]{2,}$/i.test(email)) errores.push('email');\n\n// Disposable emails: a lead you can't reply to isn't a lead\nconst dominio = email.split('@')[1] || '';\nif (['mailinator.com','yopmail.com','guerrillamail.com','10minutemail.com'].includes(dominio)) {\n  errores.push('email_desechable');\n}\n\n// Honeypot field: hidden off screen. A person doesn't see it.\n// If it comes with text, a bot filled it in.\nif (t(c.web) !== '') errores.push('bot');\n\nreturn [{\n  json: {\n    valido: errores.length === 0,\n    errores,\n    lead: {\n      nombre, email, empresa, telefono, mensaje, dominio,\n      origen: t(c.origen) || 'formulario-web',\n      recibido_en: new Date().toISOString()\n    }\n  }\n}];"
      },
