        "jsCode": "// This node runs AFTER the form has already been answered.\n// Its only job: let through only what's worth processing.\nconst item = $input.first().json;\n\n// 1) Whatever failed validation stops here.\n//    Returning an empty list stops this branch of the flow. No errors, no drama.\nif (!item.valido) return [];\n\nconst lead = item.lead;\n\n// 2) Bounce guard. First layer of duplicate control: the double click.\n//    $getWorkflowStaticData is the flow's own memory: it survives\n//    between runs while the flow is ACTIVE.\nconst memoria = $getWorkflowStaticData('global');\nif (!memoria.ultimos) memoria.ultimos = {};\n\nconst ahora = Date.now();\nconst VENTANA = 60 * 1000; // 60 seconds\n\n// Discard anything older than 10 minutes so memory doesn't grow forever\nfor (const correo of Object.keys(memoria.ultimos)) {\n  if (ahora - memoria.ultimos[correo] > 600000) delete memoria.ultimos[correo];\n}\n\nconst anterior = memoria.ultimos[lead.email];\nif (anterior && ahora - anterior < VENTANA) {\n  console.log('Bounce discarded: ' + lead.email + ' (' + Math.round((ahora - anterior) / 1000) + 's ago)');\n  return [];\n}\n\nmemoria.ultimos[lead.email] = ahora;\nreturn [{ json: { lead } }];"
