        "jsCode": "// Combines what the CRM answered with the lead, and writes the question for the AI.\nconst busqueda = $input.first().json;\n\n// To look back in the flow, you call the node by its name\nconst lead = $('Filtro').first().json.lead;\n\nconst encontrados = busqueda.results || [];\nconst existe = encontrados.length > 0;\nconst ficha = existe ? encontrados[0] : null;\n\n// Second layer of duplicate control: was it already in the CRM, and since when?\nlet dias_desde_alta = null;\nif (existe && ficha.properties && ficha.properties.createdate) {\n  dias_desde_alta = Math.round((Date.now() - new Date(ficha.properties.createdate).getTime()) / 86400000);\n}\n\n// The fixed instructions: what the AI must always do, with this lead or any other\nconst sistema = [\n  'You are the intake filter for the sales team of a Spanish company that sells management software to SMEs.',\n  'You read a message from a web form and return ONLY a JSON object. No surrounding text.',\n  'Exact fields:',\n  '- temperatura: \"caliente\" if they ask for a price, a demo, or a meeting, or say when they need it by. \"templado\" if they ask specific things with no rush. \"frio\" if it is curiosity, a student, or a vague message.',\n  '- interes: one of \"precio\", \"demo\", \"soporte\", \"colaboracion\", \"empleo\", \"spam\".',\n  '- resumen: max 20 words, in Spanish, what they ask for and why.',\n  '- urgencia: a number from 1 to 5. Only a 5 if they give a specific date or say it is urgent.',\n  '- idioma: two-letter code for the message language (\"es\", \"en\", \"ca\").',\n  'If the message is advertising, cryptocurrency, cheap SEO, or anything that is not a potential customer: interes \"spam\" and temperatura \"frio\".'\n].join('\\n');\n\n// The data for this specific lead\nconst pregunta = [\n  'Name: ' + lead.nombre,\n  'Email: ' + lead.email,\n  'Email domain: ' + lead.dominio,\n  'Company: ' + (lead.empresa || 'not given'),\n  'Phone: ' + (lead.telefono || 'not given'),\n  'Already in the CRM: ' + (existe ? 'yes, for ' + dias_desde_alta + ' days' : 'no, it is new'),\n  'Message:',\n  lead.mensaje\n].join('\\n');\n\nreturn [{\n  json: {\n    lead,\n    duplicado: existe,\n    contacto_id: existe ? ficha.id : null,\n    dias_desde_alta,\n    sistema,\n    pregunta\n  }\n}];"
