      "parameters": {
        "jsCode": "// Reads what the AI answered and makes it usable no matter what.\nconst r = $input.first().json;\nconst previo = $('Duplicado').first().json;\n\n// The API's response comes inside content[0].text\nconst bruto = String(r && r.content && r.content[0] ? r.content[0].text : '');\n\n// We keep whatever is between the first brace and the last.\n// That way it doesn't matter if the AI greets first or wraps the JSON in code fences.\nconst ini = bruto.indexOf('{');\nconst fin = bruto.lastIndexOf('}');\nlet ia = null;\nif (ini !== -1 && fin > ini) {\n  try { ia = JSON.parse(bruto.slice(ini, fin + 1)); } catch (e) { ia = null; }\n}\n\n// We never trust what a model returns: we check it against the closed\n// list of values the CRM knows how to read. If it doesn't fit, default value and move on.\nconst temps = ['caliente', 'templado', 'frio'];\nconst ints  = ['precio', 'demo', 'soporte', 'colaboracion', 'empleo', 'spam'];\nconst num   = Number(ia && ia.urgencia);\n\nconst clasificacion = {\n  temperatura: ia && temps.includes(ia.temperatura) ? ia.temperatura : 'templado',\n  interes:     ia && ints.includes(ia.interes)      ? ia.interes     : 'soporte',\n  resumen:     String(ia && ia.resumen ? ia.resumen : previo.lead.mensaje).slice(0, 200),\n  urgencia:    Number.isFinite(num) ? Math.min(5, Math.max(1, Math.round(num))) : 3,\n  idioma:      ia && /^[a-z]{2}$/.test(String(ia.idioma)) ? ia.idioma : 'es',\n  la_dijo_la_ia: ia !== null\n};\n\n// Object.assign copies what came before and adds the classification\nreturn [{ json: Object.assign({}, previo, { clasificacion }) }];"
      },
